public class OrderProcessor implements StreamApplication {
  @Override
  public void describe(StreamApplicationDescriptor appDesc) {
    KafkaSystemDescriptor kafkaDesc = new KafkaSystemDescriptor("kafka")
        .withConsumerZkConnect("zookeeper:2181")
        .withProducerBootstrapServers("broker:9092");

    KVStore<String, Integer> orderCounts =  // local RocksDB store
        appDesc.getStore("order-counts");

    MessageStream<KV<String, OrderEvent>> orders =
        appDesc.getInputStream(kafkaDesc.getInputDescriptor("orders", KVSerde.of(...)));

    orders
        .map(kv -> kv.getValue())
        .filter(order -> order.getStatus().equals("completed"))
        .partitionBy(OrderEvent::getRegion, Function.identity(), "partitioned")
        .map(kv -> {
          String region = kv.getKey();
          int count = orderCounts.getOrDefault(region, 0) + 1;
          orderCounts.put(region, count);  // local state update (no network!)
          return new KV<>(region, count);
        })
        .sendTo(appDesc.getOutputStream(kafkaDesc.getOutputDescriptor("order-counts", ...)));
  }
}
```

