// Custom stateful KeyedProcessFunction
public class FraudScorer extends KeyedProcessFunction<String, Transaction, Alert> {
    private ValueState<Double> runningTotal;    // per-user state (in RocksDB)
    private ValueState<Long> windowStart;

    @Override
    public void open(Configuration params) {
        runningTotal = getRuntimeContext().getState(
            new ValueStateDescriptor<>("total", Double.class));
        windowStart = getRuntimeContext().getState(
            new ValueStateDescriptor<>("start", Long.class));
    }

    @Override
    public void processElement(Transaction tx, Context ctx, Collector<Alert> out) {
        double total = runningTotal.value() == null ? 0 : runningTotal.value();
        total += tx.getAmount();
        runningTotal.update(total);

        if (total > 10_000) {  // $10k in session → fraud alert
            out.collect(new Alert(tx.getUserId(), total, "HIGH_SPEND"));
        }
    }
}
```

