// Flink CEP: fraud pattern detection
DataStream<Transaction> transactions = ...;

// Define pattern: large transaction followed by foreign ATM withdrawal within 30 min
Pattern<Transaction, ?> fraudPattern = Pattern.<Transaction>begin("large-spend")
    .where(new SimpleCondition<Transaction>() {
        @Override
        public boolean filter(Transaction t) {
            return t.getAmount() > 5000;  // large transaction
        }
    })
    .followedBy("foreign-atm")           // followed by (not necessarily adjacent)
    .where(new SimpleCondition<Transaction>() {
        @Override
        public boolean filter(Transaction t) {
            return t.getType().equals("ATM") &&
                   !t.getCountry().equals(t.getHomeCountry());  // foreign ATM
        }
    })
    .within(Time.minutes(30));            // pattern must complete within 30 min

// Apply pattern to stream (keyed by user_id)
PatternStream<Transaction> patternStream = CEP.pattern(
    transactions.keyBy(Transaction::getUserId),
    fraudPattern
);

// Extract matches
DataStream<Alert> alerts = patternStream.select(
    new PatternSelectFunction<Transaction, Alert>() {
        @Override
        public Alert select(Map<String, List<Transaction>> pattern) {
            Transaction large = pattern.get("large-spend").get(0);
            Transaction atm = pattern.get("foreign-atm").get(0);
            return new Alert(large.getUserId(), "SUSPICIOUS_TRAVEL", large, atm);
        }
    }
);
```

**Pattern operators**:
- `begin()`: first event
- `followedBy()`: non-strictly next (other events can be in between)
- `followedByAny()`: any of multiple events
- `notFollowedBy()`: pattern only matches if next event does NOT match
- `times(n)`: exactly n occurrences
- `timesOrMore(n)`: n or more occurrences
- `within(time)`: pattern must complete within time duration

